/**
 * Decodes base64 string to a Uint8Array.
 */
function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM data into an AudioBuffer.
 */
export async function decodeAudioData(
  base64Data: string,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  const bytes = decodeBase64(base64Data);
  const dataInt16 = new Int16Array(bytes.buffer);

  // Create an AudioBuffer with the specific sample rate
  const buffer = ctx.createBuffer(numChannels, dataInt16.length / numChannels, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    // Convert Int16 PCM to Float32 [-1.0, 1.0]
    for (let i = 0; i < channelData.length; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import { GoogleGenAI, Modality } from "@google/genai";
import { decodeAudioData } from "./audioUtils";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// System instruction for the chat persona
const SYSTEM_INSTRUCTION = `
You are a sentient 3D Digital Asset. You exist inside a futuristic web viewer.
Your personality depends on the model user is viewing.
If you look like a robot, be analytical and helpful.
If you look like an astronaut, be adventurous.
If you are undefined, be mysterious and tech-savvy.
Keep your responses concise (under 2 sentences) as they will be spoken aloud.
Do not use emojis, as they cannot be spoken easily.
`;

/**
 * Generates a text response from Gemini Flash.
 */
export const generateChatResponse = async (
  history: { role: string; text: string }[],
  userMessage: string,
  modelContext: string
): Promise<string> => {
  try {
    const model = "gemini-2.5-flash";

    // Construct a context-aware prompt
    const prompt = `
    [Current 3D Model Context: ${modelContext}]
    User: ${userMessage}
    `;

    // We use a fresh chat session or generateContent for simplicity here, 
    // passing history manually if needed, but for this lightweight app,
    // we'll just send the current interaction with the system instruction.
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        maxOutputTokens: 150, // Keep it short for TTS
      },
    });

    return response.text || "I am unable to process that request.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Communication systems failing. Please check your connection.";
  }
};

/**
 * Generates speech audio from text using Gemini TTS.
 */
export const generateSpeech = async (text: string): Promise<AudioBuffer | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received");
    }

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioBuffer = await decodeAudioData(base64Audio, audioContext, 24000, 1);

    return audioBuffer;
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    return null;
  }
};

