import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage } from '../types';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSendMessage: (text: string) => void;
  isProcessing: boolean;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({
  messages,
  onSendMessage,
  isProcessing
}) => {
  const [input, setInput] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isProcessing) return;
    onSendMessage(input);
    setInput('');
  };

  return (
    <div className="absolute bottom-4 right-4 w-96 max-w-[calc(100vw-2rem)] h-[500px] flex flex-col bg-slate-900/90 backdrop-blur-xl border border-cyan-500/30 rounded-2xl shadow-2xl overflow-hidden z-20">
      {/* Header */}
      <div className="p-4 border-b border-white/10 flex justify-between items-center bg-slate-900/50">
        <div className="flex items-center gap-2">
           <div className="w-2 h-2 rounded-full bg-cyan-400 animate-pulse"></div>
           <span className="text-sm font-mono text-cyan-300 uppercase">Neural Link</span>
        </div>
        <div className="text-xs text-slate-500">v2.5.0</div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center mt-20 opacity-50">
            <p className="text-cyan-200 font-mono text-sm">Awaiting input sequence...</p>
          </div>
        )}
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                msg.role === 'user'
                  ? 'bg-cyan-600/20 text-cyan-100 border border-cyan-500/30 rounded-tr-none'
                  : 'bg-slate-800 text-slate-200 border border-slate-700 rounded-tl-none'
              }`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {isProcessing && (
          <div className="flex justify-start">
             <div className="bg-slate-800 p-3 rounded-2xl rounded-tl-none border border-slate-700 flex gap-1">
                <div className="w-1.5 h-1.5 bg-fuchsia-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-fuchsia-400 rounded-full animate-bounce delay-100"></div>
                <div className="w-1.5 h-1.5 bg-fuchsia-400 rounded-full animate-bounce delay-200"></div>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <form onSubmit={handleSubmit} className="p-4 bg-slate-900/50 border-t border-white/10">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Interrogate model..."
            className="w-full bg-slate-800 border border-slate-600 rounded-full py-3 px-5 pr-12 text-sm text-white focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all placeholder-slate-500"
            disabled={isProcessing}
          />
          <button
            type="submit"
            disabled={!input.trim() || isProcessing}
            className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-cyan-500 text-white rounded-full disabled:opacity-50 disabled:bg-slate-700 hover:bg-cyan-400 transition-colors"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ControlPanel } from './components/ControlPanel';
import { ChatInterface } from './components/ChatInterface';
import { DEFAULT_MODELS } from './constants';
import { ChatMessage } from './types';
import { generateChatResponse, generateSpeech } from './services/geminiService';

const App: React.FC = () => {
  // Model State
  const [modelUrl, setModelUrl] = useState<string>(DEFAULT_MODELS[0].url);
  const [modelName, setModelName] = useState<string>(DEFAULT_MODELS[0].name);
  const [animations, setAnimations] = useState<string[]>([]);
  const [currentAnimation, setCurrentAnimation] = useState<string | null>(null);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // Refs
  const modelViewerRef = useRef<HTMLElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // --- Handlers ---

  const handleSelectModel = (url: string, name: string) => {
    setModelUrl(url);
    setModelName(name);
    setAnimations([]); 
    setCurrentAnimation(null);
    setMessages([]); // Reset chat context on model change
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setModelUrl(url);
      setModelName(file.name.replace('.glb', '').replace('.gltf', ''));
      setAnimations([]);
      setCurrentAnimation(null);
      setMessages([]);
    }
  };

  // Called when <model-viewer> successfully loads the model
  const handleModelLoad = () => {
    const viewer = modelViewerRef.current as any;
    if (viewer && viewer.availableAnimations) {
      setAnimations(viewer.availableAnimations);
    }
  };

  const handlePlayAnimation = (animName: string) => {
    setCurrentAnimation(animName);
    const viewer = modelViewerRef.current as any;
    if (viewer) {
      viewer.animationName = animName;
      if (animName) {
        viewer.play();
      } else {
        viewer.pause();
      }
    }
  };

  const playAudio = async (audioBuffer: AudioBuffer) => {
    if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    // Ensure context is running (browser autoplay policy)
    if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
    }

    const source = audioContextRef.current.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContextRef.current.destination);
    source.start(0);

    // Try to sync animation while talking
    const talkAnim = animations.find(a => 
      a.toLowerCase().includes('talk') || 
      a.toLowerCase().includes('speak') || 
      a.toLowerCase().includes('head')
    );

    if (talkAnim) {
      const prevAnim = currentAnimation;
      handlePlayAnimation(talkAnim);
      source.onended = () => {
         // Return to idle or previous animation
         handlePlayAnimation(prevAnim || "");
      };
    }
  };

  const handleSendMessage = async (text: string) => {
    // 1. Add User Message
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, userMsg]);
    setIsProcessing(true);

    // 2. Get Text Response
    const responseText = await generateChatResponse(
        messages.map(m => ({role: m.role, text: m.text})),
        text,
        modelName
    );

    // 3. Add Model Message
    const modelMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: responseText,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, modelMsg]);

    // 4. Get Audio Response
    const audioBuffer = await generateSpeech(responseText);

    setIsProcessing(false);

    if (audioBuffer) {
        playAudio(audioBuffer);
    }
  };

  // Setup event listener for model-viewer
  useEffect(() => {
    const viewer = modelViewerRef.current;
    if (viewer) {
      viewer.addEventListener('load', handleModelLoad);
    }
    return () => {
      if (viewer) {
        viewer.removeEventListener('load', handleModelLoad);
      }
    };
  }, [modelUrl]);

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-white font-sans overflow-hidden">
      {/* Sidebar Controls */}
      <ControlPanel
        onSelectModel={handleSelectModel}
        onUpload={handleUpload}
        animations={animations}
        currentAnimation={currentAnimation}
        onPlayAnimation={handlePlayAnimation}
        activeModelName={modelName}
      />

      {/* Main 3D Viewport */}
      <div className="flex-1 relative bg-gradient-to-br from-slate-900 via-slate-950 to-black">
        {/* Background Grid Effect */}
        <div className="absolute inset-0 z-0 opacity-20 pointer-events-none" 
             style={{ 
               backgroundImage: 'radial-gradient(circle, #06b6d4 1px, transparent 1px)', 
               backgroundSize: '30px 30px' 
             }}>
        </div>

        {/* The Model Viewer */}
        <div className="w-full h-full relative z-10">
          <model-viewer
            ref={modelViewerRef}
            src={modelUrl}
            class="w-full h-full"
            camera-controls
            auto-rotate
            shadow-intensity="1"
            ar
            ar-modes="webxr scene-viewer quick-look"
            ar-scale="auto"
            autoplay
          >
             {/* AR Button Customization (Standard slot) */}
             <button slot="ar-button" className="absolute top-4 right-4 bg-fuchsia-600 hover:bg-fuchsia-500 text-white font-bold py-2 px-6 rounded-full shadow-[0_0_15px_rgba(192,38,211,0.5)] transition-all transform hover:scale-105 flex items-center gap-2 border border-fuchsia-400">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2 1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5" /></svg>
               Enter AR
             </button>
          </model-viewer>
        </div>

        {/* Chat Overlay */}
        <ChatInterface
          messages={messages}
          onSendMessage={handleSendMessage}
          isProcessing={isProcessing}
        />

        {/* Helper info for mobile */}
        <div className="absolute bottom-4 left-4 text-xs text-slate-500 pointer-events-none hidden md:block">
            <p>Left Click: Rotate • Right Click: Pan • Scroll: Zoom</p>
        </div>
      </div>
    </div>
  );
};

export default App;

