import React, { useState, useEffect, useRef } from 'react';
import { ControlPanel } from './components/ControlPanel';
import { ChatInterface } from './components/ChatInterface';
import { QRCodeModal } from './components/QRCodeModal';
import { DEFAULT_MODELS } from './constants';
import { ChatMessage } from './types';
import { generateChatResponse, generateSpeech } from './services/geminiService';

const App: React.FC = () => {
  // Model State
  const [modelUrl, setModelUrl] = useState<string>(DEFAULT_MODELS[0].url);
  const [modelName, setModelName] = useState<string>(DEFAULT_MODELS[0].name);
  const [animations, setAnimations] = useState<string[]>([]);
  const [currentAnimation, setCurrentAnimation] = useState<string | null>(null);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // AR State
  const [showQR, setShowQR] = useState(false);

  // Refs
  const modelViewerRef = useRef<HTMLElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // --- Handlers ---

  const handleSelectModel = (url: string, name: string) => {
    setModelUrl(url);
    setModelName(name);
    setAnimations([]); 
    setCurrentAnimation(null);
    setMessages([]); // Reset chat context on model change
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setModelUrl(url);
      setModelName(file.name.replace('.glb', '').replace('.gltf', ''));
      setAnimations([]);
      setCurrentAnimation(null);
      setMessages([]);
    }
  };

  // Called when <model-viewer> successfully loads the model
  const handleModelLoad = () => {
    const viewer = modelViewerRef.current as any;
    if (viewer && viewer.availableAnimations) {
      setAnimations(viewer.availableAnimations);
    }
  };

  const handlePlayAnimation = (animName: string) => {
    setCurrentAnimation(animName);
    const viewer = modelViewerRef.current as any;
    if (viewer) {
      viewer.animationName = animName;
      if (animName) {
        viewer.play();
      } else {
        viewer.pause();
      }
    }
  };

  const playAudio = async (audioBuffer: AudioBuffer) => {
    if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    // Ensure context is running (browser autoplay policy)
    if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
    }

    const source = audioContextRef.current.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContextRef.current.destination);
    source.start(0);

    // Try to sync animation while talking
    const talkAnim = animations.find(a => 
      a.toLowerCase().includes('talk') || 
      a.toLowerCase().includes('speak') || 
      a.toLowerCase().includes('head')
    );

    if (talkAnim) {
      const prevAnim = currentAnimation;
      handlePlayAnimation(talkAnim);
      source.onended = () => {
         // Return to idle or previous animation
         handlePlayAnimation(prevAnim || "");
      };
    }
  };

  const handleSendMessage = async (text: string) => {
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, userMsg]);
    setIsProcessing(true);

    const responseText = await generateChatResponse(
        messages.map(m => ({role: m.role, text: m.text})),
        text,
        modelName
    );

    const modelMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: responseText,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, modelMsg]);

    const audioBuffer = await generateSpeech(responseText);

    setIsProcessing(false);

    if (audioBuffer) {
        playAudio(audioBuffer);
    }
  };

  // AR Trigger Logic
  const handleEnterAR = () => {
    const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

    if (isMobile) {
      const viewer = modelViewerRef.current as any;
      if (viewer && viewer.activateAR) {
        viewer.activateAR();
      }
    } else {
      setShowQR(true);
    }
  };

  // Setup event listener for model-viewer
  useEffect(() => {
    const viewer = modelViewerRef.current;
    if (viewer) {
      viewer.addEventListener('load', handleModelLoad);
    }
    return () => {
      if (viewer) {
        viewer.removeEventListener('load', handleModelLoad);
      }
    };
  }, [modelUrl]);

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-white font-sans overflow-hidden">
      {/* Sidebar Controls */}
      <ControlPanel
        onSelectModel={handleSelectModel}
        onUpload={handleUpload}
        animations={animations}
        currentAnimation={currentAnimation}
        onPlayAnimation={handlePlayAnimation}
        activeModelName={modelName}
      />

      {/* Main 3D Viewport */}
      <div className="flex-1 relative bg-gradient-to-br from-slate-900 via-slate-950 to-black">
        {/* Background Grid Effect */}
        <div className="absolute inset-0 z-0 opacity-20 pointer-events-none" 
             style={{ 
               backgroundImage: 'radial-gradient(circle, #06b6d4 1px, transparent 1px)', 
               backgroundSize: '30px 30px' 
             }}>
        </div>

        {/* The Model Viewer */}
        <div className="w-full h-full relative z-10">
          <model-viewer
            ref={modelViewerRef}
            src={modelUrl}
            class="w-full h-full"
            camera-controls
            auto-rotate
            shadow-intensity="1"
            ar
            ar-modes="webxr scene-viewer quick-look"
            ar-scale="auto"
            autoplay
            disable-zoom
          >
             {/* Note: We handle the AR Button externally for better UI control, but keep the slot empty to disable default */}
             <div slot="ar-button"></div> 
          </model-viewer>
        </div>

        {/* Global UI Overlay (AR Button) */}
        <div className="absolute top-6 right-6 z-20">
           <button 
             onClick={handleEnterAR}
             className="group relative flex items-center justify-center gap-2 bg-fuchsia-600/90 backdrop-blur-md hover:bg-fuchsia-500 text-white font-bold py-3 px-8 rounded-full shadow-[0_0_20px_rgba(192,38,211,0.6)] border border-fuchsia-400/50 transition-all transform hover:scale-105 active:scale-95 overflow-hidden"
           >
             <span className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:animate-shine"></span>
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2 1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5" /></svg>
             <span>Launch AR</span>
