      }, HTMLElement>;
    }
  }
}

import { GoogleGenAI, Modality } from "@google/genai";
import { decodeAudioData } from "./audioUtils";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
You are a sentient 3D Digital Asset named Holo. You exist inside a futuristic web viewer.
Your personality depends on the model user is viewing.
If you look like a robot, be analytical and helpful.
If you look like an astronaut, be adventurous and curious about the stars.
If you are undefined, be mysterious and tech-savvy.
Keep your responses very concise (1-2 short sentences) as they will be spoken aloud via TTS.
Do not use emojis or markdown formatting like asterisks.
`;

export const generateChatResponse = async (
  history: { role: string; text: string }[],
  userMessage: string,
  modelContext: string
): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `[Current Asset: ${modelContext}] User says: ${userMessage}`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    return response.text || "Connection to neural link lost.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Protocol error detected. System reboot required.";
  }
};

export const generateSpeech = async (text: string): Promise<AudioBuffer | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) return null;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    return await decodeAudioData(base64Audio, audioContext, 24000, 1);
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { ControlPanel } from './components/ControlPanel';
import { ChatInterface } from './components/ChatInterface';
import { QRCodeModal } from './components/QRCodeModal';
import { DEFAULT_MODELS } from './constants';
import { ChatMessage } from './types';
import { generateChatResponse, generateSpeech } from './services/geminiService';

const App: React.FC = () => {
  const [modelUrl, setModelUrl] = useState<string>(DEFAULT_MODELS[0].url);
  const [modelName, setModelName] = useState<string>(DEFAULT_MODELS[0].name);
  const [animations, setAnimations] = useState<string[]>([]);
  const [currentAnimation, setCurrentAnimation] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showQR, setShowQR] = useState(false);

  const modelViewerRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const handleSelectModel = (url: string, name: string) => {
    setAnimations([]); 
    setCurrentAnimation(null);
    setMessages([]); 
    setModelUrl(url);
    setModelName(name);
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setModelUrl(url);
      setModelName(file.name.replace('.glb', '').replace('.gltf', ''));
    }
  };

  const handleModelLoad = () => {
    const viewer = modelViewerRef.current;
    if (viewer && viewer.availableAnimations) {
      setAnimations(viewer.availableAnimations);
    }
  };

  const handlePlayAnimation = (animName: string) => {
    setCurrentAnimation(animName);
    const viewer = modelViewerRef.current;
    if (viewer) {
      viewer.animationName = animName;
      animName ? viewer.play() : viewer.pause();
    }
  };

  const playAudio = async (audioBuffer: AudioBuffer) => {
    if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
    }
    const source = audioContextRef.current.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContextRef.current.destination);
    source.start(0);

    const talkAnim = animations.find(a => 
      ['talk', 'speak', 'gesture', 'head'].some(keyword => a.toLowerCase().includes(keyword))
    );

    if (talkAnim) {
      const prevAnim = currentAnimation;
      handlePlayAnimation(talkAnim);
      source.onended = () => handlePlayAnimation(prevAnim || "");
    }
  };

  const handleSendMessage = async (text: string) => {
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', text, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setIsProcessing(true);

    const responseText = await generateChatResponse(messages, text, modelName);
    const modelMsg: ChatMessage = { id: (Date.now() + 1).toString(), role: 'model', text: responseText, timestamp: Date.now() };
    setMessages(prev => [...prev, modelMsg]);

    const audioBuffer = await generateSpeech(responseText);
    setIsProcessing(false);
    if (audioBuffer) playAudio(audioBuffer);
  };

  const handleEnterAR = () => {
    const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
    if (isMobile && modelViewerRef.current) {
      modelViewerRef.current.activateAR();
    } else {
      setShowQR(true);
    }
  };

  useEffect(() => {
    const viewer = modelViewerRef.current;
    if (viewer) {
      viewer.addEventListener('load', handleModelLoad);
    }
    return () => viewer?.removeEventListener('load', handleModelLoad);
  }, [modelUrl]);

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-white font-sans overflow-hidden">
      <ControlPanel
        onSelectModel={handleSelectModel}
        onUpload={handleUpload}
        animations={animations}
        currentAnimation={currentAnimation}
        onPlayAnimation={handlePlayAnimation}
        activeModelName={modelName}
      />

      <div className="flex-1 relative bg-gradient-to-br from-slate-900 via-slate-950 to-black overflow-hidden">
        <div className="absolute inset-0 z-0 opacity-10 pointer-events-none" 
             style={{ backgroundImage: 'radial-gradient(circle, #06b6d4 1px, transparent 1px)', backgroundSize: '40px 40px' }} />

        <div className="w-full h-full relative z-10 flex items-center justify-center">
          <model-viewer
            key={modelUrl}
            ref={modelViewerRef}
            src={modelUrl}
            class="w-full h-full"
            style={{ width: '100%', height: '100%', display: 'block', outline: 'none' }}
            camera-controls
            auto-rotate
            shadow-intensity="2"
            exposure="1.2"
            ar
            ar-modes="webxr scene-viewer quick-look"
            ar-placement="floor"
            autoplay
            crossorigin="anonymous"
            camera-orbit="0deg 75deg 10m"
          >
             <div slot="poster" className="absolute inset-0 flex items-center justify-center bg-slate-900">
                <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
             </div>
             <div slot="ar-button" style={{ display: 'none' }}></div> 
          </model-viewer>
        </div>

        <div className="absolute top-6 right-6 z-20">
           <button 
             onClick={handleEnterAR}
             className="flex items-center gap-2 bg-fuchsia-600 hover:bg-fuchsia-500 text-white font-bold py-3 px-8 rounded-full shadow-[0_0_30px_rgba(192,38,211,0.4)] border border-fuchsia-400/50 transition-all active:scale-95"
           >
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2 1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5" /></svg>
             <span>Initialize AR</span>
           </button>
        </div>

        <ChatInterface messages={messages} onSendMessage={handleSendMessage} isProcessing={isProcessing} />
        <QRCodeModal isOpen={showQR} onClose={() => setShowQR(false)} url={window.location.href} />

        <div className="absolute bottom-4 left-4 text-[10px] text-slate-500 pointer-events-none hidden md:block">
            <p>HoloChat Neural Interface • WebXR v3.2</p>
        </div>
      </div>
    </div>
  );
};

export default App;

